typedef struct Node {int value;struct Node *next;} Node;
static void clear(Node *p){while(p){Node *next=p->next;free(p);p=next;}}
int main(void){
    int n,k;if(scanf("%d%d",&n,&k)!=2||n<1||n>50||k<1||k>20)return 1;
    Node *head=NULL,*tail=NULL;
    for(int i=1;i<=n;++i){
        Node *p=malloc(sizeof *p);if(!p){clear(head);return 1;}
        p->value=i;p->next=NULL;
        if(tail)tail->next=p;else head=p;tail=p;
    }
    tail->next=head;Node *prev=tail,*cur=head;
    while(cur->next!=cur){
        for(int count=1;count<k;++count){prev=cur;cur=cur->next;}
        Node *next=cur->next;prev->next=next;free(cur);cur=next;
    }
    printf("%d\n",cur->value);free(cur);
    return 0;
}

