#include <stdio.h>
typedef struct {int id;char name[21];int score;} Record;
static int before(Record a,Record b){return a.score>b.score||(a.score==b.score&&a.id<b.id);}
int main(void){
    int n;Record a[10];if(scanf("%d",&n)!=1||n<1||n>10)return 1;
    for(int i=0;i<n;++i)if(scanf("%d%20s%d",&a[i].id,a[i].name,&a[i].score)!=3)return 1;
    for(int i=0;i<n-1;++i){int k=i;for(int j=i+1;j<n;++j)if(before(a[j],a[k]))k=j;Record t=a[i];a[i]=a[k];a[k]=t;}
    for(int i=0;i<n;++i)printf("%d %s %d\n",a[i].id,a[i].name,a[i].score);return 0;
}

