challenge.solution:
#include <stdio.h>
#include <stdlib.h>
typedef struct Node {int value;struct Node *next;} Node;
static void clear(Node *p){while(p){Node *next=p->next;free(p);p=next;}}
static int read_list(int n,Node **head){
    Node **tail=head;*head=NULL;
    for(int i=0;i<n;++i){int x;if(scanf("%d",&x)!=1)return 0;Node *p=malloc(sizeof *p);if(!p)return 0;p->value=x;p->next=NULL;*tail=p;tail=&p->next;}
    return 1;
}
static Node *merge(Node *a,Node *b){
    Node dummy={0,NULL},*tail=&dummy;
    while(a&&b){if(a->value<=b->value){tail->next=a;a=a->next;}else{tail->next=b;b=b->next;}tail=tail->next;}
    tail->next=a?a:b;return dummy.next;
}
int main(void){
    int n,m;Node *a=NULL,*b=NULL;
    if(scanf("%d%d",&n,&m)!=2||n<0||n>10||m<0||m>10)return 1;
    if(!read_list(n,&a)||!read_list(m,&b)){clear(a);clear(b);return 1;}
    Node *head=merge(a,b),*prev=NULL;while(head){Node *next=head->next;head->next=prev;prev=head;head=next;}head=prev;int first=1;
    for(Node *p=head;p;p=p->next){printf("%s%d",first?"":" ",p->value);first=0;}
    if(first)printf("EMPTY");putchar('\n');clear(head);return 0;
}

