#include <stdio.h>
typedef struct {int id,score;} Record;
int main(void){
    Record add,a[10];int n=0;
    if(scanf("%d%d",&add.id,&add.score)!=2)return 1;
    FILE *f=fopen("records.txt","a+");if(!f)return 1;
    int ok=fprintf(f,"%d %d\n",add.id,add.score)>=0;
    if(fflush(f)!=0)ok=0;
    if(fseek(f,0L,SEEK_SET)!=0)ok=0;
    if(!ok){fclose(f);return 1;}
    while(n<10){int got=fscanf(f,"%d%d",&a[n].id,&a[n].score);if(got==EOF)break;if(got!=2){fclose(f);return 1;}++n;}
    ok=!ferror(f);if(fclose(f)!=0)ok=0;if(!ok)return 1;
    for(int i=0;i<n-1;++i)for(int j=i+1;j<n;++j)
        if(a[j].score>a[i].score||(a[j].score==a[i].score&&a[j].id<a[i].id)){Record t=a[i];a[i]=a[j];a[j]=t;}
    f=fopen("records.txt","w");if(!f)return 1;
    for(int i=0;i<n;++i)if(fprintf(f,"%d %d\n",a[i].id,a[i].score)<0)ok=0;
    if(fclose(f)!=0)ok=0;if(!ok)return 1;printf("%d\n",n);return 0;
}

